import{z as p,x as A,o as l,c as d,q as n,j as i,D as t,d as r,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"专家剪枝与合并","description":"","frontmatter":{"title":"专家剪枝与合并","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/expert-pruning-merging.md","filePath":"llm/expert-pruning-merging.md","lastUpdated":1791063341000}'),B={name:"llm/expert-pruning-merging.md"};function m(u,a,h,D,g,c){const E=A("Mermaid");return l(),d("div",null,[a[2]||(a[2]=n('<h1 id="专家剪枝与合并" tabindex="-1">专家剪枝与合并 <a class="header-anchor" href="#专家剪枝与合并" aria-label="Permalink to &quot;专家剪枝与合并&quot;">​</a></h1><div class="epigraph"><p>占用低或路由高度相关的专家可以丢掉或合成一个；部署参数量按活专家计，而不是按预训练宣称的 $N$ 计。</p><footer>—— Lu et al., Not All Experts are Created Equal, 2024 一类工作；合并再压缩的思路亦见模型合并文献向专家轴的迁移</footer></div><p><a href="/llm/moe-finetuning">上一课</a>可能已经把路由锁进热点。<a href="/llm/expert-specialization">专精化分析</a> 给出冗余簇与孤点。本课动手：剪掉死专家，把冗余簇合并成更宽的一个，必要时再蒸馏回原宽度。目标是推理内存与通信，不是再刷预训练损失。后课 PEER 走向相反的百万专家；本课是把 \\(N\\) 减小。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预训练为了容量把 \\(N\\) 开大，部署时大量专家占用接近 0，却仍占显存与专家并行的切分开销。缺口是在给定下游或给定验证路由统计上，<strong>安全地减小 \\(N\\)</strong>：哪些可以删，哪些只能合，合完门怎么改。</p><p><span class="marginnote">术语翻译：专家剪枝就是「裁员」——把路由统计里几乎没人找的专家删掉；专家合并是「合并岗位」——把两个干类似活的专家揉成一个更宽的。目的都是让部署参数量对齐真实工作量，而不是预训练时宣称的 \\(N\\)。</span></p><p>删比合简单：从路由表去掉该列，token 改走次优。合要把两个 MLP 的权重合成一套，并合并它们在门里的列。合成不是张量平均那么平凡——两个专家的内部基底可能旋转。</p><p><span class="marginnote">这里的合并是专家轴，不是训练基础课里整网 SLERP。整网合并假定同一架构同一下标；专家合并先改架构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>剪枝：按验证集占用排序，删低于阈值的专家，或按干预跌点删「去掉也不疼」的。删后可短校准门。合并：对路由相关高的簇，把专家权重在适当对齐后平均或用 TIES 一类规则，门的 logits 列相加或再训一个 \\(N&#39;\\times d\\) 的新门。蒸馏：用未剪教师对剪后学生做 KL，比纯平均更稳。</p>',10)),(l(),i(o,null,{default:t(()=>[s(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E4%B8%93%E5%AE%B6%20A%20%E6%9D%83%E9%87%8D%22%5D%20--%3E%20AL%5B%22%E5%AF%B9%E9%BD%90%E5%86%85%E9%83%A8%E5%9F%BA%E5%BA%95%EF%BC%88%E5%A4%84%E7%90%86%E6%97%8B%E8%BD%AC%EF%BC%89%22%5D%0A%20%20B%5B%22%E4%B8%93%E5%AE%B6%20B%20%E6%9D%83%E9%87%8D%22%5D%20--%3E%20AL%0A%20%20AL%20--%3E%20AVG%5B%22%E5%B9%B3%E5%9D%87%E6%88%96%20TIES%20%E8%A7%84%E5%88%99%E5%90%88%E6%88%90%22%5D%0A%20%20AVG%20--%3E%20G%5B%22%E9%97%A8%E5%88%97%E7%9B%B8%E5%8A%A0%20%2F%20%E9%87%8D%E8%AE%AD%E6%96%B0%E9%97%A8%22%5D%0A%20%20G%20--%3E%20KD%5B%22%E7%9F%AD%E6%A0%A1%E5%87%86%E6%88%96%20KL%20%E8%92%B8%E9%A6%8F%E9%AA%8C%E6%94%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p><span class="marginnote">常见误区：拿预训练语料当剪枝校准集。预训练数据会「唤醒」那些部署里根本用不上的领域专家，剪枝结论与目标相反。校准集必须对齐真实部署分布——要给中文客服场景剪枝，就用中文客服流量采样，而不是通用网页。</span></p><p>校准数据应覆盖下游。用预训练数据校准会复活已死的领域专家，与部署目标相反；用过窄下游又会误删仍有用的长尾专家。</p><h3 id="与稠密化" tabindex="-1">与稠密化 <a class="header-anchor" href="#与稠密化" aria-label="Permalink to &quot;与稠密化&quot;">​</a></h3><p>把所有专家平均成一个 FFN 是极端合并，\\(k\\) 与 All-to-All 都消失。质量通常明显掉，只适合极度缺硬件。本课默认的是减 \\(N\\) 仍保持稀疏，而不是退回稠密。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>死专家占参数不占计算，剪它们几乎不改 FLOPs，但减内存与切分复杂度。冗余专家占计算，合并它们减 FLOPs 与通信。孤点既占计算又不可合，是下限 \\(N\\)。专精分析课的图在这里变成预算：先保护孤点，再合簇，最后剪死的。</p><p><span class="marginnote">为什么重要：合并不是把两个张量直接平均了事。两个专家内部的「坐标轴」（隐藏基底）可能各自旋转过，直接平均会得到两边都不像的杂交权重。先对齐基底再合成、最后用蒸馏验收——跳过对齐是合并掉点的头号原因。</span></p><p>门校准失败表现为负载重新崩到未剪专家，或质量断崖。短校准应用较小的 \\(\\gamma\\) 或辅助项，避免新崩塌。</p><p><span class="marginnote">剪完 \\(N\\) 变了，节点受限的 \\(M\\)、放置算法都要重跑。不能只改检查点里的专家列表而沿用旧并行拓扑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预训练尚未收敛时不要剪，死专家可能只是还没学到。生成式长尾任务（罕见语种）的「死」是数据假象。下一课 PEER 把 \\(N\\) 推到百万，剪枝逻辑反过来：默认几乎所有专家都极冷，检索式取出几个，不能先按占用剪到几十。本课的方法适用于 Switch / Mixtral 量级的 \\(N\\)。</p>',11)),(l(),i(o,null,{default:t(()=>[s(E,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Stat%5B%22%E5%8D%A0%E7%94%A8%E4%B8%8E%E7%9B%B8%E5%85%B3%E7%B0%87%22%5D%20--%3E%20Keep%5B%22%E4%BF%9D%E6%8A%A4%E5%AD%A4%E7%82%B9%22%5D%0A%20%20Stat%20--%3E%20Merge%5B%22%E5%90%88%E5%B9%B6%E5%86%97%E4%BD%99%E7%B0%87%22%5D%0A%20%20Stat%20--%3E%20Drop%5B%22%E5%88%A0%E9%99%A4%E6%AD%BB%E4%B8%93%E5%AE%B6%22%5D%0A%20%20Merge%20--%3E%20Cal%5B%22%E7%9F%AD%E6%A0%A1%E5%87%86%E9%97%A8%22%5D%0A%20%20Drop%20--%3E%20Cal%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"剪死专家省内存，合并冗余簇省计算与通信，孤点构成 \\(N\\) 的下限。"),e("li",null,"合并要处理门列与专家基底对齐，常需蒸馏或短校准。"),e("li",null,"校准数据应对齐部署分布；拓扑与节点约束必须重配。"),e("li",null,"不适用于百万专家检索式 MoE 的默认冷启动。"),e("li",null,"出处：Lu et al., 2024 一类专家不等价与剪枝工作。")],-1))])}const N=p(B,[["render",m]]);export{_ as __pageData,N as default};
